const incomingItems = $input.all();

// 1. Define el ORDEN EXACTO que quieres en la salida.
// He reordenado esta lista para que coincida con tu JSON de ejemplo.
const orderedColumnIds = [
  'personas__1',              // Personas
  'text8',                    // Empresa
  'estado__1',                // Industria
  'text_mksx2nnx',            // Id cuenta publicitaria
  'board_relation_mktnkez8',  // Asignación de Estrategas
  'contact_phone',            // Teléfono
  'contact_email'             // E-mail
];

const formattedItems = incomingItems.map(item => {
  const mondayItem = item.json;

  // 2. Construye el array 'column_values' en el orden definido.
  const orderedColumns = orderedColumnIds.map(columnId => {
    // 3. Por cada ID en nuestro orden, busca la columna correspondiente en los datos de entrada.
    const foundColumn = mondayItem.column_values.find(c => c.id === columnId);

    // Si la columna no existe en este item, no la añade.
    if (!foundColumn) {
      return null;
    }

    // 4. Procesa la columna encontrada (lógica que ya tenías).
    const titulo = foundColumn.column.title;
    const newColumn = {
      id: titulo,
      text: foundColumn.text,
    };

    if (titulo === 'Personas') {
      newColumn.value = foundColumn.value;
    }
    if (titulo === 'Asignación de Estrategas') {
      newColumn.value = foundColumn.value;
    }
    if (titulo === 'Industria') {
      newColumn.tags = foundColumn.column.settings_str;
    }

    return newColumn;
  }).filter(Boolean); // Elimina cualquier valor 'null' si una columna no fue encontrada.

  const desiredFormat = {
    "data": {
      "id": mondayItem.id,
      "name": mondayItem.name,
      "column_values": orderedColumns // Usa el nuevo array ordenado.
    }
  };

  return {
    json: desiredFormat
  };
});

return formattedItems;
